create or replace function public.create_project_state(project_state_input jsonb) returns public.project_states language plpgsql security invoker set search_path='' as $$ declare uid uuid:=auth.uid(); wid uuid; ps public.project_states; begin if uid is null then raise exception 'authentication_required'; end if; select wm.workspace_id into wid from public.workspace_memberships wm where wm.user_id=uid and wm.status='active' order by wm.created_at limit 1; if wid is null then raise exception 'workspace_required'; end if; insert into public.project_states(id,workspace_id,state,name,organization_id,site_location,project_type,sector,source_context,summary,priority,commercial_stage,commercial_probability,next_action,owner_user_id,created_by,created_at,updated_at) values(coalesce((project_state_input->>'id')::uuid,gen_random_uuid()),wid,coalesce(project_state_input->>'state','potential'),project_state_input->>'name',nullif(project_state_input->>'organization_id','')::uuid,project_state_input->>'site_location',project_state_input->>'project_type',project_state_input->>'sector',project_state_input->>'source_context',project_state_input->>'summary',project_state_input->>'priority',project_state_input->>'commercial_stage',nullif(project_state_input->>'commercial_probability','')::smallint,project_state_input->>'next_action',uid,uid,now(),now()) returning * into ps; insert into public.project_state_stage_requirements(project_state_id,stage,requirement_key,label,status,required,updated_by) values (ps.id,'opportunity','basic_identity','Basic project identity captured',case when nullif(trim(ps.name),'') is not null then 'satisfied'::public.readiness_state else 'not_started'::public.readiness_state end,true,uid),(ps.id,'opportunity','initial_context','Initial context captured',case when nullif(trim(ps.site_location),'') is not null or nullif(trim(ps.sector),'') is not null or nullif(trim(ps.source_context),'') is not null or nullif(trim(ps.summary),'') is not null then 'satisfied'::public.readiness_state else 'not_started'::public.readiness_state end,true,uid),(ps.id,'opportunity','next_step','Next step identified',case when nullif(trim(ps.next_action),'') is not null then 'satisfied'::public.readiness_state else 'not_started'::public.readiness_state end,true,uid); return ps; end $$; grant execute on function public.create_project_state(jsonb) to authenticated; comment on function public.create_project_state(jsonb) is 'Creates the authoritative Project State directly. Opportunity is represented by the initial state/stage and its requirements; no Opportunity entity is created.';
